import { ch, Chapter } from "./_core";

const P8: Chapter[] = [
  ch("b-wph-8", 0, "لویاتان؛ طرح کتاب", ["لویاتان — که هابز در ۱۶۵۱، در میانهٔ جنگ داخلی انگلستان نوشت — چهار بخش دارد: انسان، دولت، دولت مسیحی، و پادشاهی تاریکی. این ساختار — که از انسان‌شناسی به سیاست و از سیاست به دین می‌رود — نشان می‌دهد هابز، سیاست را نه «فن اداره»، که «هندسهٔ انسان» می‌دانست؛ و نام کتاب — هیولای دریایی کتاب ایوب — خود، مانیفست است: دولتی چنان توانا که هیچ نیرویی جز خودش نمی‌تواند بر او چیره شود."]),
  ch("b-wph-8", 1, "ماتریالیسم هابزی؛ همه‌چیز جسم", ["هابز، فلسفه‌اش را بر یک اصل می‌نهد: «هر چه هست، جسم است» — روح، خدا، و حتی «اندیشه» نیز حرکتی از حرکت‌های بدن‌اند. این ماتریالیسم — که در زمانه‌اش تکان‌دهنده بود — پیامد سیاسی دارد: اگر انسان، ماشینی است که با «حرکت» کار می‌کند، پس سیاست نیز — چون مکانیک — قابل «محاسبه» است؛ و هابز، می‌خواست برای سیاست، همان را بکند که گالیله برای فیزیک کرد: از حرکت‌های ساده، قوانین کل بسازد."]),
  ch("b-wph-8", 2, "حس و تخیل؛ مکانیک ذهن", ["هابز، ذهن را چون ماشینی تحلیل می‌کند: «حس» — حرکتی است که اشیاء بر اندام‌های ما می‌نهند؛ «تخیل» — همان حس است که «رو به خاموشی» می‌رود؛ و «ذهن» — یعنی زنجیرهٔ تخیل‌ها — چون دانه‌های تسبیح است که هر دانه، دانهٔ بعد را می‌کشد. این تحلیل — که روان‌شناسی را به فیزیک فرومی‌کاهد — برای هابز، «بنیاد» سیاست است؛ زیرا می‌خواهد نشان دهد که انسان‌ها — با همهٔ تفاوتهایشان — از «محرک‌های» مشترکی پیروی می‌کنند؛ و سیاست، دانشِ این محرک‌هاست."]),
  ch("b-wph-8", 3, "سخن و عقل؛ حساب", ["هابز — که منطقی‌گراست — «سخن» را اختراع بزرگ انسان می‌داند: واژه‌ها — که «نشانه‌ها»‌اند — به ما اجازه می‌دهند تخیل‌ها را «ثبت» کنیم؛ و «عقل» — برای هابز — چیزی جز «حساب» نیست: جمع و تفریق نام‌ها. اما این موهبت، آفتی هم دارد: «بی‌معنایی» — سخنی که حسابش درست نیست؛ و هابز می‌گوید بیشتر نزاع‌های فلسفی و دینی — که جهان را به جنگ کشانده‌اند — از همین بی‌معنایی‌هاست؛ و لویاتان — که در برابر جنگ نوشته شد — می‌خواهد با «تعریف‌های دقیق»، ریشهٔ این نزاع‌ها را بخشکاند."]),
  ch("b-wph-8", 4, "تأثرات؛ کوناتوس", ["قلب روان‌شناسی هابز، «کوناتوس» است — «کوششِ» درونی که همهٔ حرکت‌های انسان از آن برمی‌خیزد: هر موجودی، به آنچه «خوب» می‌نامدش، می‌گراید و از آنچه «بد» می‌نامدش، می‌گریزد؛ و «خوب» و «بد» — برای هابز — نه در اشیاء، که در «میل» ماست: «هر کس آنچه را میل دارد، خوب می‌نامد». این نسبیتِ ارزش‌ها — که تکان‌دهنده بود — بنیاد سیاست هابز است؛ زیرا اگر «خوبِ مشترکی» ذاتاً نباشد، پس انسان‌ها — با میل‌های متفاوت — به «جنگ» می‌افتند؛ و تنها «قدرتی مشترک» می‌تواند آنان را به صلح برساند."]),
  ch("b-wph-8", 5, "وضع طبیعی؛ جنگ همه با همه", ["هابز — با فرضی که «وضع طبیعی» خوانده شد — می‌پرسد: اگر «قدرت مشترکی» نباشد، انسان‌ها چگونه می‌زی‌اند؟ پاسخ: در «جنگ همه با همه» — و نه جنگِ همیشگی، که «آمادگیِ همیشگی برای جنگ». سه دلیل این جنگ را می‌سازند: «رقابت» — برای منابع؛ «بی‌اعتمادی» — برای امنیت؛ و «افتخار» — برای آبرو. و نتیجه، جملهٔ مشهور است: در وضع طبیعی، «زندگی انسان، تنها، فقیر، خشن، حیوانی و کوتاه است» — و هیچ صنعت، دانش، هنر و جامعه‌ای ممکن نیست. این فرض — که بعدها در نظریهٔ بازی‌ها تأیید شد — بنیاد لویاتان است."]),
  ch("b-wph-8", 6, "حق طبیعی و قانون طبیعی", ["هابز — برای بیرون‌آمدن از وضع طبیعی — دو مفهوم می‌سازد: «حق طبیعی» — آزادی هر کس برای حفظ جان خود — که در وضع طبیعی، «بی‌حد» است؛ و «قانون طبیعی» — قاعده‌ای که عقل، برای حفظ جان، کشف می‌کند — که «الزام» می‌آورد. قانون طبیعیِ نخست: «صلح را بجوی، و برای آن بکوش»; و دوم: «آنچه را برای خود نمی‌پسندی، برای دیگران مپسند» — و این، پلِ میان «حق» و «قانون» است: انسان، برای حفظ جان، باید از «همه‌چیز خواستن» — که جنگ می‌سازد — به «برابریِ خواستن» — که صلح می‌سازد — برسد."]),
  ch("b-wph-8", 7, "قوانین طبیعی؛ نوزده فرمان", ["هابز — در فصل‌های چهاردهم و پانزدهم — نوزده قانون طبیعی می‌شمارد که «خلاصهٔ اخلاق» اوست: عدالت — که وفای به عهد است؛ سپاسگزاری؛ بخشش؛ تواضع؛ انصاف؛ و مهم‌تر از همه — «غرور» را نکوهیدن — که هابز آن را ریشهٔ بسیاری از جنگ‌ها می‌داند. این قوانین — که هابز خود می‌گوید «قابل استنتاج از یک قاعده»‌اند — در وضع طبیعی، «الزام درونی» دارند؛ اما «الزام بیرونی» — یعنی ضمانت اجرا — تنها با «شمشیر» — یعنی دولت — پیدا می‌کنند؛ و این، معنای جملهٔ مشهور هابز است: «عهدها، بی‌شمشیر، جز واژه نیستند»."]),
  ch("b-wph-8", 8, "قرارداد اجتماعی؛ عهد", ["هابز — برای گذار از وضع طبیعی — «قرارداد» را می‌سازد: انسان‌ها — که از جنگ خسته‌اند و از مرگ می‌ترسند — با یکدیگر «عهد» می‌بندند که «همهٔ قدرت و قوتشان» را به «یک انسان یا یک مجلس» بسپارند؛ و این سپردن — که «تفویض» است — دولت را می‌سازد. نکتهٔ ظریف هابز این است: قرارداد، نه میان مردم و حاکم، که میان «مردم با یکدیگر» است — و حاکم، «طرف قرارداد» نیست؛ پس نمی‌تواند آن را «نقض» کند؛ و مردم — که خودشان این قدرت را ساخته‌اند — نمی‌توانند به آن «اعتراض» کنند — مگر در یک مورد، که بعداً می‌خوانیم."]),
  ch("b-wph-8", 9, "تفویض و نمایندگی؛ شخص مصنوعی", ["هابز — با مفهوم «شخص» — که از حقوق روم گرفت — دولت را می‌سازد: «شخص طبیعی» — خود انسان — و «شخص مصنوعی» — کسی که «به نام دیگری» سخن می‌گوید و عمل می‌کند؛ و حاکم، شخص مصنوعی است که «به نام همه» عمل می‌کند — و چون مردم، او را «تفویض» کرده‌اند، اعمال او، اعمال «خودشان» است. این تحلیل — که پیتکین — فیلسوف قرن بیستم — در «مفهوم نمایندگی» آن را بازسازی کرد — نشان می‌دهد هابز، «نمایندگی سیاسی» را چگونه ساخت: حاکم، نمایندهٔ مردم است — اما نماینده‌ای که پس از تفویض، «مستقل» می‌شود؛ و این، ریشهٔ بحث‌های امروز دربارهٔ «پاسخ‌گویی نمایندگی» است."]),
  ch("b-wph-8", 10, "حقوق حاکم؛ بی‌حد", ["هابز — پس از ساختن لویاتان — حقوقش را برمی‌شمارد و به «بی‌حد» بودن همهٔ آن‌ها می‌رسد: حاکم، تنها «قانون‌گذار» است — و قانون، معیار عدالت است؛ او «داور نهایی» همهٔ اختلاف‌هاست؛ او «جنگ و صلح» را تعیین می‌کند؛ او «مقام‌ها» را می‌گزیند؛ او «پاداش و کیفر» می‌دهد؛ او «عقاید» را — آنچه برای صلح لازم است — تعیین می‌کند؛ و او — مهم‌تر از همه — «تقسیم‌ناپذیر» است: قدرت، چون جان، یکی است — و تقسیمش — چنان‌که در انگلستان دیدیم — به جنگ می‌انجامد. این فهرست — که لیبرال‌ها را می‌ترساند — برای هابز، «بهای صلح» است."]),
  ch("b-wph-8", 11, "آزادی؛ نبود مانع بیرونی", ["هابز — که «جبرگرا» است — آزادی را چنین تعریف می‌کند: «نبودِ موانع بیرونی» برای حرکت؛ و انسان — که با میل‌هایش عمل می‌کند — «آزاد» است تا وقتی مانعی نباشد — حتی اگر میل‌هایش خود، معلول علل باشند. در دولت — که قانون، مانع می‌سازد — آزادی، «سکوت قانون» است: در همهٔ مواردی که قانون ساکت است — چون خرید و فروش، انتخاب مسکن، و تربیت فرزندان — مردم آزادند. این تعریف — که «آزادی منفی» خوانده شد و برلین آن را صورت‌بندی کرد — نشان می‌دهد هابز — برخلاف شهرتش — آزادی را منکر نیست؛ اما آن را «در سایهٔ قانون» می‌داند نه «در برابر قانون»."]),
  ch("b-wph-8", 12, "قانون مدنی؛ فرمان حاکم", ["هابز — که «اثبات‌گرا» است — قانون را «فرمان حاکم» می‌داند: قانون، نه «کشف» عدالت است — که عدالت، خود، ساختهٔ قانون است — و نه «عقل مشترک» — که عقل‌ها متفاوت‌اند؛ قانون، «ارادهٔ حاکم» است که با «نشانه‌های آشکار» اعلام می‌شود. اما هابز — که بی‌پروا نیست — قانون را بی‌حد نمی‌داند: قانونی که «ضد قانون طبیعی» باشد — چون فرمانِ کشتن بی‌گناه — قانون نیست؛ و قانونی که «نامفهوم» باشد — که مردم نفهمند — نیز قانون نیست. این «حدود درونی» قانون — که هابز می‌پذیرد — نشان می‌دهد اثبات‌گرایی او — چنان‌که بعدها کلسن ساخت — مطلق نیست."]),
  ch("b-wph-8", 13, "جرم و کیفر", ["هابز — که می‌خواهد «کیفر» را از «انتقام» جدا کند — جرم را «نقض قانون» می‌داند — و نه «نقض اخلاق»؛ و کیفر را — نه «بهره‌کشی از جرم» — که «اصلاح آینده»: هدف کیفر، نه انتقام گذشته — که گذشته نمی‌گذرد — که «بازداشتن» جرم‌کار و دیگران از آینده است. و چون کیفر — برای اصلاح است — باید «متناسب» باشد — نه چنان سبک که باز ندارد و نه چنان سنگین که به «ظلم» بدل شود — و هابز، شکنجه را — که برای «کشف» است نه «کیفر» — رد می‌کند. این تحلیل — که برای قرن هفدهم، پیشرو بود — بر اصلاحات کیفری بعدی — از بکاریا تا امروز — اثر گذاشت."]),
  ch("b-wph-8", 14, "دولت مسیحی؛ دین و سیاست", ["بخش سوم لویاتان — «دولت مسیحی» — به رابطهٔ دین و سیاست می‌پردازد؛ و موضع هابز — که «اراستیانی» خوانده شد — این است: «تفسیر دین» — چون هر تفسیر دیگری — می‌تواند به نزاع بینجامد؛ پس باید «حاکم» — که حافظ صلح است — «مفسر نهایی» دین نیز باشد. هابز — که کتاب مقدس را می‌خواند — می‌گوید: پادشاهی خدا — که در عهد عتیق است — پادشاهیِ «این‌جهانی» بود؛ و مسیح — که پادشاهی‌اش «از این جهان نیست» — فرمانی سیاسی نداد. این فصل — که کلیسا را خشمگین کرد و کتاب را در انگلستان و فرانسه ممنوع ساخت — از بحث‌انگیزترین بخش‌های لویاتان است."]),
  ch("b-wph-8", 15, "پادشاهی تاریکی؛ نقد خرافه", ["بخش چهارم — «پادشاهی تاریکی» — حملهٔ هابز به «تفسیرهای نادرست» است — که او آن‌ها را «پادشاهی تاریکی» می‌خواند: نخست، تفسیرهای خرافی از کتاب مقدس — که «روح‌ها» و «جن‌ها» را چنان می‌سازند که مردم از آن‌ها — نه از قانون — بترسند؛ دوم، فلسفهٔ ارسطویی — که با واژه‌های بی‌معنا — چون «جوهر مجرد» — مردم را گیج می‌کند؛ سوم، سنت‌های نادرست — که تاریخ را تحریف می‌کنند؛ و چهارم، منافع شخصی — که همهٔ این‌ها را برای «قدرت» نگه می‌دارد. این فصل — که هابز را «دشمن خرافه» می‌سازد — از ریشه‌های روشنگری است؛ و خواننده می‌بیند که لویاتان — که مدافع قدرت مطلق است — هم‌زمان، از شجاع‌ترین نقدهای دینی زمانهٔ خود نیز هست."]),
  ch("b-wph-8", 16, "زمینهٔ تاریخی؛ جنگ داخلی", ["لویاتان — که بدون جنگ داخلی انگلستان — ۱۶۴۲ تا ۱۶۵۱ — قابل فهم نیست — در پاسخ به پرسشی نوشته شد که هابز و هم‌نسلانش هر روز می‌دیدند: «چرا انسان‌ها — که برادرند — یکدیگر را می‌کشند؟» پاسخ هابز: چون «قدرت مشترکی» نیست که آنان را بازدارد؛ و جنگ داخلی — که شاه و مجلس، هر دو مدعی حاکمیت بودند — «وضع طبیعی» بود که به درون جامعه آمده بود. لویاتان — که در ۱۶۵۱، درست پس از اعدام چارلز یکم منتشر شد — می‌گوید: راه نجات، نه بازگشت به شاه — که ساختن «حاکمیتی بی‌رقیب» است؛ و این، معنای سیاسی کتاب است."]),
  ch("b-wph-8", 17, "هابز و گالیله؛ روش هندسی", ["هابز — که در ۱۶۳۶ با گالیله دیدار کرد — از او «روش» گرفت: چنان‌که گالیله، حرکت اجسام را به «قوانین» فروکاهد، هابز می‌خواست حرکت انسان‌ها را — با میل‌ها و ترس‌هایشان — به قوانین فروکاهد؛ و «هندسه» — که هابز آن را تنها دانش یقینی می‌دانست — الگوی او شد: از «تعریف‌ها» — چون تعریف وضع طبیعی — به «قضایا» — چون لزوم دولت — برسد. این روش — که «هندسی» خوانده شد — بر اسپینوزا اثر گذاشت — که اخلاق را «به شیوهٔ هندسی» نوشت — و بر روسو — که قرارداد اجتماعی را با «اصول» ساخت. و خواننده می‌بیند که لویاتان — با همهٔ محتوای سیاسی‌اش — پیش از هر چیز، «پروژهٔ روشی» است."]),
  ch("b-wph-8", 18, "هابز و بلاغت؛ اقناع", ["هابز — که در جوانی توسیدید را ترجمه کرد — اهمیت «بلاغت» را می‌دانست؛ اما در لویاتان، با آن می‌جنگد: بلاغت — که «احساسات» را برمی‌انگیزد — برای «حقیقت» خطرناک است؛ زیرا مردم را — نه با دلیل، که با «شور» می‌راند. هابز — که خود نثری قدرتمند دارد — می‌خواست کتابش را «دلیل‌مند» بنویسد نه «شورانگیز»؛ اما — و این طنز است — جملات او — چون «زندگیِ تنها و فقیر و خشن» — خود از شoranگیزترین جملات زبان انگلیسی‌اند. این دوگانگی — فیلسوفی که از بلاغت می‌گریزد و بدان می‌افتد — از موضوعات جالب هابزپژوهی است؛ و برای هر نویسنده‌ای، آینه‌ای است."]),
  ch("b-wph-8", 19, "ابله؛ چرا وفای به عهد", ["هابز — در فصل پانزدهم — با «ابله» — که می‌گوید «عدالت، عقلانی نیست؛ هر کس باید سود خود را بجوید، حتی با شکستن عهد» — روبه‌رو می‌شود؛ و این، جدی‌ترین اعتراض به قرارداد است. پاسخ هابز — که دو بخش دارد — چنین است: نخست، شکستن عهد — در درازمدت — به «ضرر» خودِ شکستنده است؛ زیرا او را از «اتحاد» — که برای بقا لازم است — بیرون می‌راند؛ و دوم — که ظریف‌تر است — کسی که عهد می‌شکند، اگر «موفق» شود، نمی‌تواند بر موفقیتش «حساب» کند — و عقل، بر «شانس» بنا نمی‌شود. این پاسخ — که بحث‌های فراوانی برانگیخت — امروز با «نظریهٔ بازی‌ها» — که نشان می‌دهد همکاری، در بازی‌های تکرارشونده، عقلانی است — تقویت شده است."]),
  ch("b-wph-8", 20, "حق مقاومت؛ حد لویاتان", ["هابز — که حاکم را بی‌حد می‌داند — یک «حد» را می‌پذیرد که از همه مهم‌تر است: «حق مقاومت». چون هدف قرارداد — «حفظ جان» است، هر فرمانی که جان را تهدید کند — چون فرمانِ کشتن خود، یا اعتراف به جرمی که نکردی — لازم‌الاطاعه نیست؛ و اگر حاکم — که حافظ جان است — دیگر نتواند جان را حفظ کند — چنان‌که در جنگ شکست خورد — «حق اطاعت» نیز پایان می‌یابد. این حد — که کوچک می‌نماید — در حقیقت، بنیادین است؛ زیرا نشان می‌دهد لویاتان — که بی‌حد می‌نماید — خود، «مشروط» به هدفی است: حفظ جان؛ و اگر این هدف برافتد، لویاتان نیز برافتاده است."]),
  ch("b-wph-8", 21, "لوایاتان و تصویر نخست؛ بدن سیاسی", ["تصویر نخست لویاتان — که مشهورترین تصویر تاریخ فلسفهٔ سیاسی است — هیولایی را نشان می‌دهد که بدنش از «هزاران انسان کوچک» ساخته شده — و در دو دستش، شمشیر و عصای اسقفی دارد. این تصویر — که خلاصهٔ کتاب است — می‌گوید: لویاتان، «خدای فانی» است — ساختهٔ دست انسان‌ها — که همهٔ آنان را در خود دارد؛ و شمشیر و عصا — قدرت نظامی و دینی — هر دو در دست اوست. هابز — که این تصویر را سفارش داد — می‌خواست بگوید: قدرت سیاسی و دینی — که در انگلستان، دو سپاه ساختند — باید «یکی» شوند؛ وگرنه، جنگ، پایان نمی‌یابد."]),
  ch("b-wph-8", 22, "هابز و لاک؛ پاسخ", ["لاک — که چهل سال بعد «دو رساله دربارهٔ حکومت» را نوشت — مستقیم‌ترین پاسخ به هابز است: وضع طبیعی — برای لاک — «جنگ» نیست؛ «آزادی و برابری» است با قانون طبیعی؛ حق مالکیت — که هابز آن را ساختهٔ دولت می‌داند — برای لاک، «پیش از دولت» است؛ و قرارداد — که برای هابز، سپردنِ همهٔ حقوق است — برای لاک، «سپردن مشروط» است: مردم، حق «داوری» را می‌سپارند، نه حق «حیات و آزادی و مالکیت» را؛ و اگر حاکم به این حقوق تجاوز کند، مردم حق «انقلاب» دارند. این دو — که هر دو از «قرارداد» آغاز می‌کنند و به دو جهان می‌رسند — نشان می‌دهند که «مبنا» — به تنهایی — «نتیجه» را تعیین نمی‌کند."]),
  ch("b-wph-8", 23, "هابز و روسو؛ نقد", ["روسو — در «گفتار دربارهٔ نابرابری» — هابز را نقد می‌کند: انسانِ وضع طبیعیِ هابز — که حریص و ترسان است — «انسان طبیعی» نیست؛ «انسان اجتماعیِ فاسد» است که هابز، به گذشته فرافکنده است. انسان طبیعی — برای روسو — نه شرور است و نه خیر — «بی‌تفاوت» است؛ و شر — که هابز آن را ذاتی می‌داند — محصول «جامعه» است — چون مالکیت و رقابت. اما روسو — در قرارداد اجتماعی — از هابز می‌آموزد: «ارادهٔ عام» — که روسو می‌سازد — وارث «حاکمیت بی‌تقسیم» هابز است؛ و خواننده می‌بیند که نقد روسو بر هابز — با همهٔ تندی‌اش — از دل خود هابز برمی‌خیزد."]),
  ch("b-wph-8", 24, "نظریهٔ بازی‌ها؛ هابز امروز", ["هابز — که سه قرن پیش از ریاضیاتِ استراتژی می‌نوشت — امروز با «نظریهٔ بازی‌ها» خوانده می‌شود: وضع طبیعی — که در آن هر کس، با عقل خودش، به «جنگ» می‌رسد — نمونهٔ کامل «معمای زندانی» است: دو زندانی — که هر دو با «خیانت»، برای خود بهتر می‌کنند — اما اگر «هر دو همکاری کنند»، برای هر دو بهتر است. و راه‌حل — که در بازی‌های تکرارشونده پیدا شد — «اعتمادِ قابل نظارت» است — و این، دقیقاً کارِ لویاتان است: با «نظارت و کیفر»، همکاری را عقلانی می‌کند. این خوانش — که هابز را از «فیلسوف استبداد» به «فیلسوف همکاری» بدل می‌کند — از جالب‌ترین تحولات هابزپژوهی معاصر است."]),
  ch("b-wph-8", 25, "گوتی؛ منطق نمایندگی", ["پیتکین — در «مفهوم نمایندگی» — که از مهم‌ترین کتاب‌های فلسفهٔ سیاسی قرن بیستم است — تحلیل هابز از «تفویض» را بازسازی می‌کند: هابز — برای نخستین بار — نمایندگی را نه «تشابه» — که نماینده شبیه مردم باشد — که «اختیار» می‌سازد: نماینده، کسی است که مردم، «به نام او عمل کردن» را به او داده‌اند. این تحلیل — که نمایندگی مدرن — از پارلمان تا وکیل — را می‌سازد — اما پرسشی را باز می‌گذارد: اگر نماینده، پس از تفویض، «مستقل» شود — چنان‌که هابز می‌خواهد — «پاسخ‌گویی» چه می‌شود؟ این پرسش — که هابز را به نقد می‌کشد — از میراث‌های زندهٔ اوست."]),
  ch("b-wph-8", 26, "اشمیت؛ مفهوم سیاسی", ["کارل اشمیت — حقوق‌دان آلمانی — در «مفهوم سیاسی» — هابز را «فیلسوفِ تصمیم» خواند: برای هابز — که از جنگ می‌گریزد — «دوست و دشمن» — که اشمیت آن را معیار سیاست می‌داند — باید توسط «یک نفر» تعیین شود؛ و این «تصمیم‌گرایی» — که اشمیت ساخت — از دل هابز برمی‌خیزد. اشمیت — که بعداً با نازیسم همراه شد — هابز را «تکنولوژیست» می‌خواند: کسی که دولت را «ماشین» کرد و روحش را کشت. این خوانش — که بحث‌انگیز است — نشان می‌دهد هابز، مانند همهٔ بزرگان، «ظرف تفسیرهای متعارض» است؛ و خواننده باید بداند که هر خوانشی از هابز — از لیبرالی تا تصمیم‌گرا — خودش نیز موضع سیاسی دارد."]),
  ch("b-wph-8", 27, "اوکشات؛ مقدمهٔ کلاسیک", ["مایکل اوکشات — که مقدمه‌اش بر لویاتان — ۱۹۴۶ — از مشهورترین مقدمه‌های فلسفی است — هابز را «فیلسوفِ اراده» می‌خواند: برای هابز — برخلاف سنت عقل‌گرا — «اراده» — نه «عقل» — بنیاد سیاست است؛ و قرارداد، نه کشفِ عقلی، که «تصمیم» است. اوکشات — که خود محافظه‌کار بود — هابز را از «بنیان‌گذار لیبرالیسم» می‌داند — نه دموکراسی؛ زیرا لیبرالیسم — که از ارادهٔ فرد آغاز می‌کند — به هابز نزدیک‌تر است تا دموکراسی — که از «خیر مشترک» آغاز می‌کند. این خوانش — که هابز را «لیبرالِ اقتدارگرا» می‌سازد — از بحث‌انگیزترین خوانش‌های قرن بیستم است."]),
  ch("b-wph-8", 28, "اسکینتر؛ هابز و جمهوری‌خواهی", ["کوئنتین اسکینر — مورخ مکاتب فکری — در «هابز و آزادی جمهوری‌خواهانه» — نشان می‌دهد هابز، در «عنصرها» و «شهروند» — آثار پیشینش — آزادی را چنان تعریف می‌کرد که با «وابستگی» ناسازگار نبود؛ اما در لویاتان — که پس از اعدام شاه نوشت — تعریفش را تغییر داد: آزادی را به «نبود مانع بیرونی» فروکاهد تا «وابستگی به حاکم» را با «آزادی» ناسازگار نسازد. این کشف — که نشان می‌دهد هابز، تعاریفش را «سیاسی» تغییر داد — از مهم‌ترین یافته‌های تاریخ‌نگاری فلسفه است؛ و به خواننده می‌آموزد که متون را — نه تنها «چه می‌گویند» — که «چرا چنین می‌گویند» بخواند."]),
  ch("b-wph-8", 29, "هابز و روابط بین‌الملل؛ رئالیسم", ["هابز — که وضع طبیعی را میان «دولت‌ها» نیز می‌دید — از بنیان‌گذاران «رئالیسم» در روابط بین‌الملل است: دولت‌ها — که بر سرشان «لویاتانی» نیست — در وضع طبیعی‌اند؛ و «شمشیر» — نه «حقوق» — ضامن بقاست. این نگاه — که مورگنتاو و والتز آن را ساختند — امروز نیز زنده است؛ اما خواننده باید بداند که هابز — برخلاف شهرتش — «جنگ دائمی» میان دولت‌ها را نمی‌خواست؛ می‌گفت: «پادشاهان — چون در وضع طبیعی‌اند — همواره آمادهٔ جنگ‌اند؛ اما جنگِ همیشگی نمی‌کنند» — و «صلحِ مسلح» — که هابز توصیف می‌کند — همان چیزی است که «موازنهٔ قوا» خوانده شد."]),
  ch("b-wph-8", 30, "هابز و فمینیسم", ["هابز — که «پدرسالاری» فیلمر را رد می‌کند — در لویاتان می‌گوید: فرمان‌روایی بر کودکان — که «پدری» خوانده می‌شود — در حقیقت، می‌تواند «مادری» نیز باشد — زیرا در وضع طبیعی، کودک، نخست با مادر است؛ و فرمان‌روایی، نه از «جنسیت»، که از «قرارداد» یا «قدرت» می‌آید. این صفحه — که برای زمانه‌اش شگفت‌انگیز است — فمینیست‌های هابزی — چون کارول پیتیمن — را برانگیخت: پتیمن — در «قرارداد جنسی» — می‌گوید قرارداد اجتماعی — که هابز و لاک و روسو ساختند — بر «قراردادی پنهان» استوار است: قراردادِ «مردان» بر «زنان»؛ و خواننده می‌بیند که نقد فمینیستی — حتی بر پیشروترین متون — راه‌گشاست."]),
  ch("b-wph-8", 31, "روان‌شناسی هابز؛ تأثرات", ["روان‌شناسی هابز — که در فصل‌های ششم تا یازدهم است — از ماندگارترین بخش‌های لویاتان است: او، «تأثرات» را — چون امید و ناامیدی، شجاعت و ترس، عشق و نفرت — «حرکت‌های درونی» می‌داند که به «کنش» می‌انجامند؛ و «شخصیت» را — که «عادات تأثرات» است — قابل ساختن می‌داند. نکتهٔ ظریف هابز: «کنجکاوی» — که او آن را «اشتیاق دانستن علل» می‌داند — تأثری است که انسان را از حیوان جدا می‌کند؛ و «خنده» — که از «احساس برتری ناگهانی» برمی‌خیزد — نشانهٔ «ضعف» است نه قوت. این تحلیل‌ها — که چهار قرن بعد، روان‌شناسی آن‌ها را با نام‌های دیگر بازکشف کرد — نشان می‌دهد هابز، «روان‌شناس» بود پیش از آنکه روان‌شناسی باشد."]),
  ch("b-wph-8", 32, "هابز و زبان؛ اسم‌گرایی", ["هابز — که «اسم‌گرا» است — می‌گوید: «کلیات» — چون «انسانیت» — در خارج نیستند؛ تنها «نام‌ها»‌اند که ما برای راحتی می‌سازیم؛ و حقیقت، نه «مطابقت با اشیاء» — که «درست‌بودنِ ترکیب نام‌ها» است. این اسم‌گرایی — که از اوکام گرفت — پیامد بزرگی دارد: اگر حقیقت، «ترکیب درست نام‌ها» است، پس «تعریف‌ها» — که نام‌ها را می‌سازند — مهم‌ترین کار فلسفه‌اند؛ و لویاتان — که با تعریف‌های دقیق آغاز می‌شود — می‌خواهد با «تعریف‌های درست»، از «نزاع‌های بی‌معنا» جلوگیری کند. این نگاه — که بر فلسفهٔ تحلیلی قرن بیستم — از فرگه تا ویتگنشتاین — اثر گذاشت — از میراث‌های زندهٔ هابز است."]),
  ch("b-wph-8", 33, "هابز و زیبایی‌شناسی؛ ذوق و قضاوت", ["هابز — که زیبایی‌شناسی را «جدی» گرفت — در «انسان» — بخش نخست لویاتان — می‌گوید: «ذوق» — که هنر را داوری می‌کند — نه ذاتی است و نه مطلق؛ «عادت» و «آموزش» آن را می‌سازند؛ و «طنز» — که او آن را «ذوقِ درست» می‌داند — از «تصورِ ناگهانیِ شباهت میان نامتجانس‌ها» برمی‌خیزد. این تحلیل — که بر نظریه‌های طنز — تا فروید — اثر گذاشت — نشان می‌دهد هابز — که او را فیلسوفِ خشک می‌دانند — به «لطافت‌ها» نیز نظر داشت؛ و لویاتان — که با جدال می‌جنگد — خود، با طنزی ظریف نوشته شده است — و خواننده‌ای که این طنز را نبیند، نیمی از هابز را از دست داده است."]),
  ch("b-wph-8", 34, "لویاتان و بهیموث؛ دو هیولا", ["هابز — که پس از لویاتان، «بهیموث» — تاریخ جنگ داخلی — را نوشت — دو «هیولا» را در برابر هم می‌نهد: لویاتان — هیولای دریایی — که «دولت» است؛ و بهیموث — هیولای خشکی — که «جنگ داخلی» است. بهیموث — که گفت‌وگویی است میان دو شخص — نشان می‌دهد که جنگ داخلی — که لویاتان را ساخت — چگونه «از درون» — با تعصب دینی و جاه‌طلبی مجلس — زاده شد. این دو کتاب — که باید با هم خوانده شوند — می‌گویند: لویاتان — که از «ترس بهیموث» ساخته شد — تنها با «شناخت بهیموث» قابل فهم است؛ و خواننده می‌بیند که هابز — فیلسوفِ هندسه — هم‌زمان، «تاریخ‌نگارِ فاجعه» نیز بود."]),
  ch("b-wph-8", 35, "هابز و توسیدید؛ درس جنگ", ["هابز — که در جوانی، «تاریخ جنگ پلوپونز» توسیدید را ترجمه کرد — از او «درس» گرفت: جنگ — که میان آتن و اسپارت بود — نه از «بدی انسان‌ها» — که از «ساختار» — یعنی نبود قدرت برتر — برمی‌خیزد؛ و «ترس» — که آتن را به امپراتوری کشاند — نیروی اصلی سیاست است. لویاتان — که این درس را به داخل جامعه برد — می‌گوید: همان ساختاری که میان شهرها جنگ می‌سازد — نبود حاکم — میان انسان‌ها نیز جنگ می‌سازد؛ و راه نجات — در هر دو — «قدرتی برتر» است. این پیوند — که «رئالیسم» را ساخت — نشان می‌دهد هابز، سیاست را «یکپارچه» می‌دید: همان قوانین، هم در داخل و هم در خارج جاری‌اند."]),
  ch("b-wph-8", 36, "زندگی هابز؛ ترس و فلسفه", ["هابز — که در ۱۵۸۸، سال حملهٔ آرمادا، به دنیا آمد — می‌گفت: «مادرم، دو قلو زایید: من و ترس»؛ و این «ترس» — که با او ماند — کلید فلسفه‌اش است: لویاتان — که از «ترس مرگ» ساخته می‌شود — فلسفهٔ مردی است که ترس را می‌شناخت. هابز — که در جنگ داخلی، از ترس جانش به فرانسه گریخت و لویاتان را در تبعید نوشت — پس از بازگشت، با پارلمان کنار آمد و در نهادهشت‌وپنج‌سالگی، در حال ترجمهٔ هومر، مرد. این زندگی — که «ترس» و «عقل» را درهم آمیخت — به خواننده می‌آموزد که فلسفه‌ها — از آسمان نمی‌آیند؛ از «زیست» فیلسوفان برمی‌خیزند."]),
  ch("b-wph-8", 37, "لویاتان در ایران؛ ترجمه و reception", ["لویاتان — که با ترجمهٔ حسین بشیریه به فارسی آمد — برای خوانندهٔ ایرانی، دو درس ویژه دارد: نخست، «مسئلهٔ دولت» — که هابز آن را «ساختنی» می‌داند نه «داده‌شده» — برای جامعه‌ای که در سدهٔ اخیر، با «مسئلهٔ دولت‌سازی» روبه‌رو بوده، زنده است؛ و دوم، «نسبت دین و سیاست» — که بخش سوم لویاتان آن را طرح می‌کند — برای خواننده‌ای که فقه سیاسی خوانده، گفت‌وگویی می‌سازد: هابز — که دین را زیر سیاست می‌آورد — با سنت فقهی — که سیاست را زیر دین می‌آورد — در «تقابل سازنده» است؛ و این تقابل — که نباید به پذیرش یا ردّ بینجامد — از آموزنده‌ترین گفت‌وگوها برای خوانندهٔ ایرانی است."]),
  ch("b-wph-8", 38, "هابز و حقوق بشر", ["هابز — که «حقوق طبیعی» را ساخت — اما آن را «حق هر کس بر همه‌چیز» خواند — با حقوق بشرِ مدرن رابطه‌ای دوگانه دارد: از یک سو، مفهوم «حق» — که لاک و اعلامیه‌ها آن را ساختند — از هابز برمی‌خیزد؛ و از سوی دیگر، هابز — که حق را با «دولت» محدود می‌کند — با حقوق بشرِ «فرا-دولتی» ناسازگار است. این دوگانگی — که بحث‌های فراوانی برانگیخته — پرسشی را باز می‌گذارد: آیا «حقوق» — بی‌دولتی که آن را ضمانت کند — «حقوق» است یا «آرزو»؟ این پرسش — که هابز طرح کرد — امروز، در بحث «مداخلهٔ بشردوستانه» و «حاکمیت ملی»، زنده‌تر از همیشه است."]),
  ch("b-wph-8", 39, "هابز و دموکراسی", ["هابز — که سلطنت را می‌ستود — اما دموکراسی را نیز «امکان‌پذیر» می‌دانست: لویاتان — که «حاکم» را می‌سازد — می‌تواند «یک نفر» باشد یا «یک مجلس»؛ و مجلس — که می‌تواند «همهٔ مردم» باشد — دموکراسی است. هابز — که دموکراسی مستقیم را — چون آتن — ناپایدار می‌دانست — می‌گفت: دموکراسی، اگر بخواهد بماند، باید «نمایندگی» را بپذیرد — وگرنه، به هرج‌ومرج می‌افتد. این تحلیل — که هابز را «دموکراتِ ناخواسته» می‌سازد — نشان می‌دهد لویاتان — برخلاف شهرتش — نه «ضد دموکراسی» — که «ضد هرج‌ومرج» است؛ و دموکراسیِ قانون‌مدار — که هابز می‌پذیرد — از دموکراسی‌های مدرن، بی‌فاصله نیست."]),
  ch("b-wph-8", 40, "هابز و اقتصاد؛ ثروت و قدرت", ["هابز — که اقتصاد را «شاخهٔ سیاست» می‌داند — در فصل بیست‌وچهارم لویاتان، به «تغذیهٔ دولت» می‌پردازد: ثروت — که از زمین، دریا و صنعت برمی‌خیزد — باید چنان توزیع شود که «فقرِ مضر» نباشد — زیرا فقیرِ گرسنه، به «سرقت» می‌افتد و امنیت را می‌شکند؛ و «انبارهای عمومی» — که هابز پیشنهاد می‌کند — باید برای «روزهای قحطی» آماده باشند. این صفحات — که هابز را «پیشرو دولت رفاه» می‌سازند — نشان می‌دهند لویاتان — که او را فیلسوفِ بازار آزاد می‌خوانند — به «تأمین همگانی» نیز نظر داشت؛ و خواننده می‌بیند که برچسب‌ها — حتی دربارهٔ هابز — ساده‌اند."]),
  ch("b-wph-8", 41, "هابز و آموزش؛ دانشگاه‌ها", ["هابز — که دانشگاه‌های انگلستان را — که ارسطویی و کاتولیک‌مآب بودند — «قلعه‌های پادشاهی تاریکی» می‌خواند — می‌خواست آموزش را «دولتی» و «عقلانی» کند: دانشگاه‌ها — که کشیشان را تربیت می‌کنند — باید «شهروندان» را تربیت کنند؛ و کتاب‌های درسی — که با خرافه پرند — باید با «فلسفهٔ درست» — که لویاتان است — جایگزین شوند. این نگاه — که آموزش را «سلاح دولت» می‌داند — از یک سو، پیشرو است — آموزش همگانی و عقلانی — و از سوی دیگر، نگران‌کننده — دولتی‌کردن حقیقت؛ و خواننده باید این دوگانگی را — که در همهٔ نظام‌های آموزشی زنده است — جدی بگیرد."]),
  ch("b-wph-8", 42, "هابز و خانواده؛ قدرت پدری", ["هابز — که «پدرسالاری فیلمر» — که سلطنت را از «حق پدر» می‌گرفت — را رد می‌کند — می‌گوید: فرمان‌روایی بر خانه — که «پدری» خوانده می‌شود — نه «طبیعی» است و نه «از جنسیت» — از «قرارداد» یا «قدرت» است؛ و در وضع طبیعی، «مادر» — که کودک با اوست — فرمان‌رواست. این تحلیل — که برای زمانه‌اش تکان‌دهنده بود — «خانواده» را نیز «سیاسی» می‌کند: همان منطقی که دولت را می‌سازد — قرارداد برای امنیت — خانواده را نیز می‌سازد. و خوانندهٔ فمینیست — که پتیمن را خوانده — می‌بیند که هابز — با همهٔ پیشروی‌اش — در عمل، خانوادهٔ پدرسالار زمانه‌اش را نگه داشت؛ و این تناقض، خود، درس است."]),
  ch("b-wph-8", 43, "هابز و مجازات اعدام", ["هابز — که کیفر را «برای آینده» می‌داند نه «برای گذشته» — دربارهٔ مجازات اعدام — که در زمانه‌اش رایج بود — موضعی ظریف دارد: از یک سو، می‌گوید: کسی که به «قتل» محکوم شده — که جان دیگران را گرفته — از حمایت قانون بیرون است؛ و از سوی دیگر، می‌گوید: کسی که «فرمان اعدام خود» را بگیرد — حق «فرار» دارد — زیرا هدف قرارداد، حفظ جان بود، نه از دست دادن آن. این تناقض ظاهری — که هابز را به «لغزش» متهم کرده — در حقیقت، نشان می‌دهد او می‌خواست «حق حیات» را — حتی در دل استبدادش — نگه دارد؛ و این حد — که کوچک می‌نماید — بنیادین است."]),
  ch("b-wph-8", 44, "هابز و معجزه؛ دین عقلانی", ["هابز — که در فصل‌های دینی لویاتان، «معجزه» را نیز می‌سنجد — می‌گوید: معجزه — که «اثری فراتر از طبیعت» خوانده می‌شود — باید با «عقل» سنجیده شود؛ و بسیاری از «معجزه‌های ادعایی» — که خرافه‌فروشان برای «قدرت» می‌سازند — با عقل ناسازگارند. اما هابز — که «ملحد» خوانده شد — معجزه را یکسره رد نمی‌کند؛ می‌گوید: «ما — که از طبیعت، کم می‌دانیم — نباید آنچه را نمی‌فهمیم، رد کنیم»؛ و این «تواضع معرفتی» — که هابز را از جزمیتِ هر دو سو نگه می‌دارد — از ظرایف اوست. خواننده می‌بیند که هابز — با همهٔ ماتریالیسمش — «ندانم‌گرا» بود نه «منکر»."]),
  ch("b-wph-8", 45, "هابز و اخلاق؛ نسبیت و قانون", ["اخلاق هابز — که «نسبی» آغاز می‌کند — به «قانون» می‌انجامد: خوب و بد — که در وضع طبیعی، «میل» ماست — در دولت، «قانون» می‌شود؛ و عدالت — که در وضع طبیعی، بی‌معناست — در دولت، «وفای به عهد» است. این حرکت — که اخلاق را از «ذات» به «ساخت» می‌برد — پرسشی را باز می‌گذارد: اگر عدالت، ساختهٔ قانون است — و قانون، فرمان حاکم — آیا «عدالتِ ناعادلانه» ممکن است؟ هابز — که این پرسش را می‌شنود — پاسخ می‌دهد: قانونی که «ضد قانون طبیعی» باشد — چون فرمانِ ظلم — قانون نیست؛ و این حد — که اخلاق را پیش از قانون نگه می‌دارد — میراث هابز برای فلسفهٔ حقوق است."]),
  ch("b-wph-8", 46, "لویاتان و عصر دیجیتال؛ نظارت", ["لویاتان — که «نظارت» را برای امنیت لازم می‌داند — در عصر دیجیتال، از نو خوانده می‌شود: دولت‌ها — که با فناوری، می‌توانند «همه‌چیز» را ببینند — لویاتان‌هایی‌اند که هابز خوابش را نمی‌دید؛ و پرسش این است: آیا «امنیت» — که بهای لویاتان بود — هنوز، بهای «نظارت همگانی» را می‌پردازد؟ فوکو — که «جامعهٔ نظارتی» را ساخت — هابز را می‌خواند؛ و زوبوف — که «سرمایه‌داری نظارتی» را ساخت — نشان می‌دهد که نظارت، از دولت به «شرکت‌ها» منتقل شده است. خواننده می‌بیند که لویاتان — با چهار قرن فاصله — هنوز می‌تواند آینهٔ زمانه باشد؛ و پرسش هابز — «چقدر امنیت، به چه بهایی؟» — پرسشِ امروز است."]),
  ch("b-wph-8", 47, "نقد لیبرالی؛ هابز و آزادی", ["منتقدان لیبرال هابز — از میل تا امروز — می‌گویند: لویاتان — که آزادی را «سکوت قانون» می‌داند — آزادی را «کم» می‌شمارد؛ زیرا بسیاری از مهم‌ترین آزادی‌ها — چون آزادی بیان و وجدان — در «سکوت قانون» نیستند — بلکه باید «ضد قانون» باشند — یعنی قانون، نباید بدان‌ها دست بزند. این نقد — که درست است — اما نباید فراموش کرد که هابز — که آزادی بیانِ مطلق را — که به «فتوای قتل» می‌انجامد — رد می‌کند — می‌خواست آزادی را «مسئولانه» کند؛ و خواننده می‌بیند که نزاع لیبرال و هابزی — بر سر «حد آزادی» — هنوز، از زنده‌ترین نزاع‌هاست."]),
  ch("b-wph-8", 48, "روش خواندن لویاتان", ["برای خواندن لویاتان — که با نثر قرن هفدهمی و استدلال‌های متراکم نوشته شده — این روش پیشنهاد می‌شود: نخست، «فهرست فصل‌ها» را بخوانید — که هابز، چون مهندس، نقشهٔ کتاب را پیش از آن می‌دهد؛ دوم، فصل‌های سیزدهم تا پانزدهم — وضع طبیعی، قرارداد و قوانین طبیعی — را — که قلب کتاب‌اند — با دقت بخوانید و «دفترچهٔ تعریف‌ها» بسازید؛ سوم، فصل‌های هفدهم تا بیست‌ویکم — دولت، آزادی و حقوق حاکم — را با «پرسش تطبیقی» بخوانید؛ و چهارم، بخش‌های دینی را — که کم‌خوانده‌اند — برای فهم «هابزِ کامل» بخوانید. با این روش، لویاتان — که اغلب «کتاب استبداد» خوانده می‌شود — به «کتابِ پرسش» بدل می‌شود: چه چیزی، ما را از جنگ نگه می‌دارد؟"]),
  ch("b-wph-8", 49, "جمع‌بندی؛ هابز و ما", ["پنجاه فصل این سیر — از ماتریالیسم تا نظارت دیجیتال — لویاتان را پیمود؛ و اکنون خواننده می‌داند که این کتاب — با همهٔ دفاعش از قدرت مطلق — «کتاب صلح» است: هابز — که جنگ را دید — می‌خواست راهی بسازد که انسان‌ها، بدون کشتن یکدیگر، با هم بزی‌اند؛ و لویاتان — که این راه بود — با همهٔ خطرهایی که دارد — از «جنگ همه با همه» بهتر است. میراث هابز — که لیبرالیسم، رئالیسم، و نظریهٔ بازی‌ها از آن برخاستند — نشان می‌دهد که حتی «اشتباه‌ترین» پاسخ‌ها — اگر جدی باشند — می‌توانند «درست‌ترین» پرسش‌ها را بسازند؛ و خواننده‌ای که لویاتان را خوانده، دیگر نمی‌تواند «دولت» را بدیهی بداند — و این، نخستین گام فهم سیاست است.", ["پروژه‌های پیشنهادی", "برای مقطع پژوهشی، چند پروژه پیشنهاد می‌شود: «هابز و مسئلهٔ دولت‌سازی در ایران معاصر»؛ «وضع طبیعی هابز و نظریهٔ بازی‌ها»؛ «تفویض هابزی و پاسخ‌گویی نمایندگی در مجلس»؛ و «هابز و غزالی؛ ترس و سیاست در دو سنت». هر یک از این پروژه‌ها — اگر با خوانش مستقیم لویاتان و روش تطبیقی انجام شود — می‌تواند خواننده را از خوانندهٔ هابز، به گفت‌وگوکننده با هابز برساند."]]),
];

const P9: Chapter[] = [
  ch("b-wph-9", 0, "اخلاق؛ به شیوهٔ هندسی", ["اخلاق اسپینوزا — که با نام کامل «اخلاق، اثبات‌شده به شیوهٔ هندسی» آمد — از عجیب‌ترین کتاب‌های تاریخ فلسفه است: قضیه‌ها، براهین، و نتیجه‌ها — چون هندسهٔ اقلیدس. اما محتوایش — خدا، تأثرات، و رهایی — از هندسه، دورتر است. اسپینوزا — که می‌خواست فلسفه را از «خطابت» — که احساسات را برمی‌انگیزد — به «برهان» برساند — این روش را برگزید تا بگوید: حقایق اخلاقی — چون حقایق هندسی — «لازم»‌اند؛ و خواننده — که ابتدا با فرم می‌جنگد — کم‌کم می‌فهمد که این فرم، خود، بخشی از پیام است."]),
  ch("b-wph-9", 1, "جوهر؛ آنچه در خود است", ["اسپینوزا، اخلاق را با تعریفی آغاز می‌کند که همهٔ کتاب از آن برمی‌خیزد: «جوهر، چیزی است که در خود است و از راه خود تصور می‌شود» — یعنی برای بودن و فهمیده‌شدن، به چیزی جز خود نیاز ندارد. از این تعریف — که اسپینوزا آن را از دکارت گرفت — نتیجه‌ای برمی‌خیزد که دکارت را تکان داد: اگر جوهر، به غیر نیاز ندارد، پس «دو جوهر» — که دکارت می‌گفت — نمی‌تواند باشد؛ زیرا هر جوهر، دیگری را برای بودن لازم نمی‌دارد — و آنچه به غیر نیاز ندارد، نمی‌تواند «از غیر» آمده باشد. پس جوهر، «یکی» است؛ و این «یکی» — که اسپینوزا آن را «خدا» می‌خواند — همهٔ آنچه هست را در خود دارد."]),
  ch("b-wph-9", 2, "صفت‌ها و حالت‌ها", ["اسپینوزا — که جوهر را یکی می‌داند — «صفت‌ها» و «حالت‌ها» را می‌سازد تا «کثرت» را توضیح دهد: «صفت» — آنچه فهم، از جوهر به‌مثابه ذاتش درک می‌کند — چون «گسترش» و «تفکر»؛ و «حالت» — آنچه از جوهر برمی‌خیزد و در غیر است — چون این بدن و این ذهن. و چون جوهر، یکی است و بی‌نهایت صفت دارد — که ما، تنها دو صفتش را می‌شناسیم — پس همهٔ آنچه هست — از ستاره‌ها تا اندیشه‌ها — «حالت‌های» یک جوهرند؛ و «من» و «تو» — که خود را جوهر می‌پنداریم — در حقیقت، «حالت‌هایی» از آن یکی‌ایم. این وارونه‌نگری — که انسان را از «مرکز» به «حالت» می‌برد — تکان اخلاق است."]),
  ch("b-wph-9", 3, "خدا یا طبیعت", ["مشهورترین جملهٔ اسپینوزا — Deus sive Natura — «خدا، یا طبیعت» — خلاصهٔ متافیزیک اوست: خدای اسپینوزا — نه خدای ادیان ابراهیمی است — که فراتر از جهان، آن را «می‌سازد» — و نه طبیعتِ ماده‌گرایان است — که بی‌روح است؛ خدا-طبیعت، «کلِّ لازمِ هستی» است — که همه‌چیز، از ضرورت ذاتش برمی‌خیزد. این خدا — که نه اراده‌ای چون ما دارد و نه هدفی — «علت درونی» جهان است نه «علت بیرونی»؛ و خوانندهٔ مکتب‌خانه — که وحدت وجود را در عرفان خوانده — شباهت و تفاوت را می‌بیند: اسپینوزا — با برهان — به جایی می‌رسد که ابن‌عربی — با شهود — رسید؛ اما راه‌ها و نتیجه‌ها، یکی نیستند."]),
  ch("b-wph-9", 4, "طبیعت‌ساز و طبیعت‌ساخته", ["اسپینوزا — برای توضیح رابطهٔ خدا و جهان — تمایزی می‌سازد که از قرون وسطی گرفت: «طبیعت‌ساز» — natura naturans — خدا به‌مثابه «علت فعال» — یعنی جوهر با صفت‌هایش؛ و «طبیعت‌ساخته» — natura naturata — خدا به‌مثابه «مجموعهٔ معلول‌ها» — یعنی همهٔ حالت‌ها. این تمایز — که ظاهراً فنی است — از مهم‌ترین ابزارهای فهم اسپینوزاست: خدا — نه «جدا از» جهان است — که «در» جهان است — اما نه «مجموعِ» جهان؛ و جهان — نه «آفریدهٔ» خداست — که «لازمهٔ» ذات اوست. و خواننده می‌بیند که این تمایز — که برای الهیات، تکان‌دهنده بود — برای فلسفهٔ طبیعت، راه‌گشا شد."]),
  ch("b-wph-9", 5, "جبرگرایی؛ ضرورت همه‌جا", ["اسپینوزا — که ضرورت را از ذات خدا می‌گیرد — «جبرگرا» است: هیچ چیز — در عالم — «ممکن‌الوقوع» نیست — چنان‌که ما می‌پنداریم؛ همه‌چیز — از حرکت ستاره‌ها تا تصمیم‌های ما — از «ضرورت طبیعت» برمی‌خیزد؛ و «تصادف» — که ما بدان ایمان داریم — فقط نامِ «جهل ما به علل» است. این جبرگرایی — که اخلاق را تهدید می‌کند — برای اسپینوزا، «رهایی» است؛ زیرا — چنان‌که بعداً می‌خوانیم — «آزادی» برای او، نه «انتخاب بی‌علت» — که «شناخت ضرورت» است؛ و خواننده می‌بیند که اسپینوزا — با جبرگرایی‌اش — راهی می‌رود که رواقیان رفتند؛ اما با برهانی که آنان نداشتند."]),
  ch("b-wph-9", 6, "نفی غایت‌مندی؛ ضربه به الهیات", ["اسپینوزا — در ضمیمهٔ بخش یکم — بر «غایت‌مندی» می‌تازد: ما — چون با «میل» عمل می‌کنیم — می‌پنداریم طبیعت نیز با «هدف» عمل می‌کند؛ و چون چیزها برایمان «سودمند»‌اند — می‌پنداریم «برای ما» ساخته شده‌اند؛ و چون گاه «زیان‌بار»‌اند — می‌پنداریم «خدا خشمگین» است. اسپینوزا می‌گوید: این «توهّم غایت‌مندی» — که ریشهٔ الهیات عامیانه است — باید ریشه‌کن شود؛ زیرا طبیعت — که از ضرورت ذات خدا برمی‌خیزد — «هدف» ندارد؛ و پرسش «برای چه؟» — دربارهٔ طبیعت — بی‌معناست. این ضربه — که کانت، دو قرن بعد، آن را تعدیل کرد — از شجاع‌ترین صفحات تاریخ فلسفه است."]),
  ch("b-wph-9", 7, "آزادی؛ ضرورتِ آگاهانه", ["اسپینوزا — که جبرگراست — اما «آزادی» را نیز می‌سازد — با تعریفی که اخلاق را می‌سازد: «آزاد، چیزی است که از ضرورتِ ذاتِ خود عمل می‌کند؛ و ضروری، چیزی که از غیر عمل می‌کند». پس آزادی — نه «انتخاب بی‌علت» است — که «خودعلتی»؛ و انسان — که تا وقتی از «تأثرات بیرونی» عمل می‌کند، «برده» است — وقتی از «ذاتِ فهمیدهٔ» خود عمل کند، «آزاد» می‌شود. این آزادی — که «شناخت» می‌سازدش — معنایش روشن است: هرچه عللِ کنش‌هایت را بیشتر بشناسی — و از تأثراتِ کور به فهم روشن بروی — آزادتری؛ و خواننده می‌بیند که اخلاق اسپینوزا — نه کتاب «بایدها» — که کتاب «فهم‌ها» است."]),
  ch("b-wph-9", 8, "عقل و ارادهٔ خدا؛ نقد اختیاریت", ["اسپینوزا — که می‌خواهد خدا را از «انسان‌انگاری» برهاند — می‌گوید: «عقل و ارادهٔ خدا» — چنان‌که ما می‌فهمیم — در خدا نیست؛ زیرا عقل و اراده — که «تفکر»‌اند — از صفت‌های خدایند — نه از ذاتش؛ و خدایی که «می‌اندیشد و می‌خواهد» — چون ما — خدایی است که «حالت» است نه «جوهر». این نقد — که الهیات را خشمگین کرد — برای اسپینوزا، «تنزیه» است: خدا — که «علت درونی» همه‌چیز است — نمی‌تواند «چون ما» تصمیم بگیرد؛ و «ارادهٔ خدا» — که الهیات بدان تکیه می‌کند — فقط نامِ «ضرورتِ طبیعت» است. خوانندهٔ کلام — که بحث صفات خدا را خوانده — شباهت این نقد را با نقد «تشبیه» در الهیات اسلامی می‌بیند."]),
  ch("b-wph-9", 9, "بخش دوم؛ ذهن و بدن", ["بخش دوم اخلاق — «دربارهٔ ماهیت و خاستگاه ذهن» — با قضیه‌ای آغاز می‌شود که دوگانه‌انگاری دکارت را می‌شکافد: «ذهن، ایدهٔ بدن است». این جمله — که عجیب می‌نماید — معنایش چنین است: چون تفکر و گسترش — دو صفتِ یک جوهرند — پس هر «حالت گسترده» — چون بدن — «ایده‌ای» دارد — چون ذهن؛ و ذهن و بدن — نه دو «چیز» — که «یک چیز» از دو زاویه‌اند. این «دووجهی» — که دکارت را بی‌نیاز می‌کند — چون «تعامل» میان دو جوهر دیگر لازم نیست — یکی از شگفت‌انگیزترین راه‌حل‌های مسئلهٔ ذهن و بدن است؛ و خوانندهٔ فلسفهٔ ذهن — که در درس تأملات گذشتیم — می‌بیند که اسپینوزا، راهی رفت که قرن بیستم — با «هویت‌گرایی دووجهی» — دوباره رفت."]),
  ch("b-wph-9", 10, "موازی‌گرایی؛ نظم و ارتباط", ["اسپینوزا — برای توضیح رابطهٔ ذهن و بدن — «موازی‌گرایی» را می‌سازد: «نظم و ارتباط ایده‌ها، همان است که نظم و ارتباط اشیاء» — یعنی هر رویداد بدنی، «ایده‌ای» دارد و هر ایده، «رویداد بدنی»؛ و این دو — چون دو ترجمه از یک متن‌اند — همواره با هم می‌روند — بی‌آنکه بر هم «اثر» بگذارند. این موازی‌گرایی — که ظاهراً غریب است — نتیجهٔ مهمی دارد: «ارادهٔ ذهن» و «حرکت بدن» — که ما آن‌ها را «علت و معلول» می‌پنداریم — در حقیقت، «یک رویداد»‌اند که دو روایت دارد؛ و «تصمیم گرفتم و دستم بلند شد» — نه دو رویداد — که یک رویداد است که از درون «تصمیم» و از بیرون «بلند شدن» خوانده می‌شود."]),
  ch("b-wph-9", 11, "تخیل؛ نخستین شناخت", ["اسپینوزا — که شناخت را سه مرتبه می‌داند — «تخیل» را نخستین مرتبه می‌شمارد: شناختی که از «اثر اشیاء بر بدن» برمی‌خیزد — چون دیدن خورشید که «دو وجب» می‌نماید — و چون از «بدن ما» — که متأثر است — برمی‌خیزد، «ناقص» است؛ اما — و این نکتهٔ ظریف است — تخیل، «خطا» نیست — زیرا «ایدهٔ» درستِ اثر است؛ خطا — که «محرومیت از شناخت کامل» است — وقتی می‌آید که این شناخت ناکامل را «کامل» بپنداریم. این تحلیل — که خطا را «کمبود» می‌داند نه «مثبت» — برای خوانندهٔ معرفت‌شناسی — که در درس دکارت گذشتیم — راه‌گشاست؛ و نشان می‌دهد اسپینوزا — با جبرگرایی‌اش — چگونه «مسئولیت شناختی» را نگه می‌دارد."]),
  ch("b-wph-9", 12, "عقل؛ دومین شناخت", ["مرتبهٔ دوم شناخت — «عقل» — شناختی است که از «مفاهیم مشترک» برمی‌خیزد — یعنی از آنچه در همهٔ چیزها مشترک است — چون «گسترش» و «حرکت و سکون»؛ و چون این مفاهیم — از «ذات» چیزها برمی‌خیزند نه از «اثرشان» بر ما — شناختی «کامل» و «ضروری» می‌سازند. عقل — که هندسه نمونهٔ آن است — به ما می‌آموزد که چیزها «چگونه» از ضرورت طبیعت برمی‌خیزند؛ و این «چگونه» — که فهم علل است — «قدرت» می‌آورد؛ زیرا هرچه علل را بیشتر بدانیم، کمتر بردهٔ آن‌هاییم. و اسپینوزا — که اخلاق را با هندسه نوشت — می‌خواست به خواننده نشان دهد که «فهمیدن» — نه «خواستن» — راه رهایی است."]),
  ch("b-wph-9", 13, "شهود؛ سومین شناخت", ["مرتبهٔ سوم شناخت — «شهود» — شناختی است که «از ایدهٔ مناسبِ ذاتِ خدا برمی‌خیزد» و «ماهیت چیزها را در خدا» می‌بیند — یعنی چیزها را نه به‌صورت پراکنده، که «در کل». این شهود — که اسپینوزا آن را «عالی‌ترین» می‌داند — همان چیزی است که «عشق عقلانی خدا» می‌سازد؛ و چون از «فهم ضرورت همه‌چیز» برمی‌خیزد — به «رضایت» می‌انجامد — رضایتی که رواقیان «آموختن طبیعت» می‌خواندند. خوانندهٔ عرفان — که «شهود» را در گلشن راز خوانده — شباهت را می‌بیند؛ اما تفاوت را نیز: شهود اسپینوزا — نه «فنا» — که «فهم» است؛ نه از راه ترک عقل — که از راه «کمال عقل»؛ و این تفاوت، مرز فلسفه و عرفان است."]),
  ch("b-wph-9", 14, "مفاهیم مشترک؛ پل ذهن و جهان", ["«مفاهیم مشترک» — که اسپینوزا آن‌ها را از «رسائل کوتاه» گرفت — از کلیدی‌ترین مفاهیم اخلاق‌اند: مفاهیمی — چون «گسترش» — که در همهٔ اجسام مشترک‌اند و «بسته به بدنِ خاصی» نیستند؛ و چون «مشترک»‌اند، «ایده‌هایشان» نیز در همهٔ ذهن‌ها مشترک است — و این، پایهٔ «تفاهم» است. دُلوز — که اخلاق را «کتاب مفاهیم» می‌خواند — می‌گوید: مفاهیم مشترک — که «اجتماعی‌ترین» مفاهیم‌اند — پایهٔ «اجتماع» نیز هستند؛ زیرا جامعه — نه از میل‌های خصوصی — که از «مشترکات» ساخته می‌شود. این خوانش — که اسپینوزا را فیلسوفِ «مشترک» می‌داند — از زنده‌ترین خوانش‌های معاصر است."]),
  ch("b-wph-9", 15, "خطا و کذب؛ محرومیت", ["اسپینوزا — که «کذبِ مثبت» را رد می‌کند — می‌گوید: ذهن — از آنجا که «ایدهٔ بدن» است — هرگز «خطا نمی‌کند» به معنای «گزارش نادرست»؛ آنچه «خطا» می‌نامیم، «محرومیت از شناخت کامل» است: وقتی بدن، از چند چیز، اثری «مشترک و مبهم» می‌گیرد — چون دیدن خورشید از دور — ذهن، این ابهام را «واقعیت» می‌پندارد. پس خطا — نه از «ارادهٔ آزاد» — چنان‌که دکارت می‌گفت — که از «ناقصی» برمی‌خیزد؛ و راه درمانش — نه «مراقبت از اراده» — که «افزودن بر شناخت» است. این تحلیل — که اخلاقِ شناخت را می‌سازد — برای خواننده‌ای که می‌خواهد «کمتر خطا کند»، راهی روشن می‌گشاید: بیشتر بفهم."]),
  ch("b-wph-9", 16, "ابدیت ذهن؛ چه می‌ماند", ["اسپینوزا — در پایان بخش پنجم — می‌گوید: «بخشی از ذهن، ابدی است» — جمله‌ای که خوانندگان را گیج کرده است. معنایش چنین است: ذهن — از آنجا که «ایدهٔ بدن» است — با بدن می‌ماند تا وقتی بدن هست؛ اما «ایده‌های مناسب» — که از شناخت دوم و سوم برمی‌خیزند — چون «حقایق ابدی»‌اند — در «خدا» می‌مانند؛ و هرچه بیشتر از این شناخت‌ها داشته باشیم، «بخش ابدی» ذهن — که «عقل» است — بزرگ‌تر می‌شود. این «ابدیت» — که نه «جاودانگی شخصی» است و نه «تناسخ» — معنایش این است: آنچه از ما می‌ماند — نه «خاطرات» — که «فهم‌ها»ست؛ و خواننده می‌بیند که اسپینوزا — که جاودانگی عامیانه را رد می‌کند — جاودانگیِ «دانایی» را می‌سازد."]),
  ch("b-wph-9", 17, "بخش سوم؛ خاستگاه تأثرات", ["بخش سوم اخلاق — «دربارهٔ خاستگاه و ماهیت تأثرات» — با پیشگفتاری آغاز می‌شود که از شجاع‌ترین صفحات فلسفه است: اسپینوزا می‌گوید فیلسوفان — که تأثرات را «رذیلت‌هایی که باید سرکوب شوند» می‌خوانند — «به جای فهمیدن، می‌خندند یا می‌گریند»؛ و من — که می‌خواهم تأثرات را چون «خط‌ها و سطوح» — بی‌طرفانه — بررسی کنم — می‌گویم: تأثرات — چون همه‌چیز — از «ضرورت طبیعت» برمی‌خیزند؛ و «طوفان و خشم انسان» — چون «طوفان هوا» — عللی دارد که باید شناخت. این نگاه — که تأثرات را «طبیعی» می‌داند — راه روانکاوی را چهار قرن پیش گشود؛ و فروید — که اسپینوزا را می‌خواند — مدیون همین پیشگفتار است."]),
  ch("b-wph-9", 18, "کوناتوس؛ جوهر اخلاق", ["قلب بخش سوم — «کوناتوس» است: «هر چیز — تا آنجا که در خودش است — در ماندنِ بودنش می‌کوشد» — و این کوشش — که «ذات» هر چیز است — در انسان — از آنجا که «ذهن و بدن» است — «اشتها» خوانده می‌شود. این اصل — که اسپینوزا آن را بنیاد اخلاق می‌سازد — می‌گوید: «خوب» — نه آنچه «دستور» داده شده — که «آنچه ماندنِ بودنمان را یاری می‌کند»؛ و «بد» — آنچه آن را می‌کاهد. پس اخلاق — برای اسپینوزا — نه «اطاعت» — که «افزایش قدرت هستی» است؛ و خواننده می‌بیند که اخلاق اسپینوزا — که نیچه آن را ستود — «اخلاقِ زندگی» است نه «اخلاقِ مرگ»."]),
  ch("b-wph-9", 19, "شادی، غم و میل؛ سه تأثر اصلی", ["اسپینوزا — که می‌خواهد همهٔ تأثرات را از چند اصل بسازد — سه تأثر «اصلی» می‌شمارد: «میل» — که خودِ کوناتوس است به‌مثابه آگاهی؛ «شادی» — گذار از کمال کمتر به بیشتر؛ و «غم» — گذار از کمال بیشتر به کمتر. و همهٔ تأثرات دیگر — که اسپینوزا چهل‌وهشت‌تایشان را برمی‌شمارد — از ترکیب این سه با «ایدهٔ علت» برمی‌خیزند: «عشق» — شادیِ همراه با ایدهٔ علت بیرونی؛ «نفرت» — غمِ همراه با ایدهٔ علت؛ «امید» — شادیِ ناپایدار از آینده؛ و «ترس» — غمِ ناپایدار از آینده. این «هندسهٔ تأثرات» — که شگفت‌انگیز است — نشان می‌دهد اسپینوزا — چون ریاضی‌دان — می‌خواست «نقشهٔ» روح را بکشد؛ و خواننده می‌بیند که اخلاق — برای او — «جغرافیا» است نه «قانون»."]),
  ch("b-wph-9", 20, "تأثرات فعال و منفعل", ["اسپینوزا — که همهٔ تأثرات را از کوناتوس می‌سازد — میان «تأثرات فعال» و «منفعل» تمایز می‌گذارد: تأثر «فعال» — چون شادیِ فهم — آن است که «علت کافی‌اش» در خود ماست — یعنی از ذاتِ فهمیده‌مان برمی‌خیزد؛ و تأثر «منفعل» — چون خشم و حسد — آن است که علتش — جزئی — در «بیرون» است. و چون «آزادی» — برای اسپینوزا — «خودعلتی» است — پس هرچه تأثراتمان «فعال‌تر» باشند — آزادتریم؛ و هرچه «منفعل‌تر» — برده‌تر. این تمایز — که ساده می‌نماید — عمیق است: خشم — که از «زیانِ بیرونی» برمی‌خیزد — برده‌ای است که «بیرون» بر ما تحمیل کرده؛ و شادیِ فهم — که از «خودمان» برمی‌خیزد — آزادی است."]),
  ch("b-wph-9", 21, "عشق و نفرت؛ هندسهٔ رابطه", ["اسپینوزا — که عشق را «شادیِ همراه با ایدهٔ علت بیرونی» تعریف می‌کند — نتایجی می‌گیرد که تکان‌دهنده‌اند: ما چیزها را — چون «شادی» می‌بخشند — «خوب» می‌خوانیم؛ و چون «خوب» خواندیم — بیشتر دوست‌شان می‌داریم — و این دور — که «عادت» می‌سازد — ریشهٔ وابستگی‌هاست. و «نفرت» — که «غم همراه با ایدهٔ علت» است — می‌کوشد علتش را «نابود» کند — اما چون نفرت — خود «غم» است — نفرت‌ورز — پیش از منفور — می‌رنجد؛ پس عقل — که می‌خواهد «شادی» را بیفزاید — نفرت را — نه با نفرت — که با «عقل» پاسخ می‌دهد. این تحلیل — که «چرخهٔ نفرت» را می‌شکافد — برای خواننده‌ای که در جامعه‌ای پر از نفرت زندگی می‌کند، راه‌گشاست."]),
  ch("b-wph-9", 22, "تقلید تأثرات؛ همدلی", ["اسپینوزا — که می‌خواهد «اجتماع» را نیز از تأثرات بسازد — «تقلید تأثرات» را می‌سازد: ما — چون با انسان‌های «همانندِ» خود «مشترکات» داریم — تأثراتشان را «تقلید» می‌کنیم: شادیِ دیگری — چون شبیه ماست — ما را شاد می‌کند؛ و غمش — ما را غمگین؛ و این «همدلی» — که اسپینوزا آن را طبیعی می‌داند — پایهٔ «اخلاق اجتماعی» است. اما اسپینوزا — که واقع‌بین است — می‌افزاید: همین تقلید — «حسد» را نیز می‌سازد — زیرا شادیِ «همانند» — وقتی با «مقایسه» همراه شود — به غم ما بدل می‌شود. این تحلیل — که شبکه‌های اجتماعی، آن را هر روز نشان می‌دهند — از ماندگارترین یافته‌های روان‌شناسی اجتماعی است."]),
  ch("b-wph-9", 23, "بخش چهارم؛ بردگی انسان", ["بخش چهارم — «دربارهٔ بردگی انسان» — می‌پرسد: چرا انسان — که «می‌داند» چه برایش خوب است — باز «بد» می‌کند؟ پاسخ اسپینوزا — که جبرگراست — این است: چون «دانستن» — به تنهایی — «قدرت» نمی‌آورد؛ تأثرات — که «قدرت‌های واقعی»‌اند — اگر «قوی‌تر» از فهم باشند — بر ما چیره می‌شوند؛ و «برده» — برای اسپینوزا — کسی است که «تأثراتش» — که از بیرون می‌آیند — بر «فهمش» — که از درون می‌آید — چیره‌اند. پس بردگی — نه «زنجیر بیرونی» — که «ساختار درونی» است؛ و راه رهایی — نه «سرکوب تأثرات» — که «ساختن تأثرات قوی‌تر» — تأثراتِ فهم — است. این تحلیل — که اخلاق را «مهندسی تأثرات» می‌کند — برای خوانندهٔ معاصر — که با اعتیادها و وسوسه‌ها می‌جنگد — راه‌گشاست."]),
  ch("b-wph-9", 24, "قدرت تأثرات؛ چرا عقل می‌بازد", ["اسپینوزا — که می‌خواهد بگوید چرا «عقل» — با همهٔ روشنی‌اش — گاه می‌بازد — قانونی می‌سازد: «تأثر را — جز تأثری قوی‌تر و مخالف — نمی‌توان مهار کرد» — یعنی «تأثر» را با «دلیل» نمی‌توان کشت — با «تأثر» می‌توان. پس کسی که می‌خواهد از «خشم» رها شود — نباید فقط «بفهمد» که خشم بد است — باید «شادیِ فهم» را — که تأثری قوی‌تر است — در خود بسازد؛ و این «ساختن» — که با تمرین و محیط می‌شود — هنر اخلاق است. این قانون — که روان‌درمانی‌های معاصر — چون درمان مبتنی بر پذیرش — آن را کشف کرده‌اند — از ماندگارترین آموزه‌های عملی اخلاق است؛ و خواننده می‌بیند که اسپینوزا — فیلسوفِ هندسه — هم‌زمان «روان‌درمانگر» نیز بود."]),
  ch("b-wph-9", 25, "خوب و مفید؛ بازتعریف", ["اسپینوزا — که می‌خواهد اخلاق را از «دستورهای آسمانی» به «زمین» بیاورد — «خوب» و «بد» را بازتعریف می‌کند: «خوب» — آنچه «می‌دانیم» برای ماندنِ بودنمان «مفید» است؛ و «بد» — آنچه «می‌دانیم» مانع آن است. این تعریف — که «مفید» را جای «حلال» می‌نشاند — دو پیامد دارد: نخست، اخلاق — «نسبی به هر کس» می‌شود — آنچه برای من مفید است — با آنچه برای تو مفید است — ممکن است متفاوت باشد؛ و دوم، اخلاق — «شناختی» می‌شود — زیرا «دانستنِ مفید» — خود، بخشی از خوبی است. این بازتعریف — که نیچه آن را «فراسوی نیک و بد» خواند — از شجاع‌ترین حرکات تاریخ اخلاق است."]),
  ch("b-wph-9", 26, "جامعه؛ انسان برای انسان", ["اسپینوزا — که فردگرا می‌نماید — اما «اجتماع» را نیز می‌سازد: «انسان — برای انسان — مفیدترین چیز است» — زیرا هیچ چیز — چون انسانِ فهمیده — نمی‌تواند «ماندنِ بودن» ما را یاری کند؛ و چون «عقل» — که در همه مشترک است — همه را به «چه چیز برای همه مفید است» می‌خواند — پس عقلانی‌ترین انسان — اجتماعی‌ترین نیز هست. این نتیجه — که از «کوناتوس فردی» به «خیر مشترک» می‌رسد — از شگفت‌انگیزترین حرکات اخلاق است؛ و خواننده می‌بیند که اسپینوزا — که او را فردگرا می‌خوانند — در حقیقت، «اجتماعی‌ترین» فیلسوفان است؛ زیرا جامعه را — نه بر «قرارداد» — که بر «طبیعت فهم» می‌نهد."]),
  ch("b-wph-9", 27, "انسان آزاد؛ فرمان‌های عقل", ["اسپینوزا — در پایان بخش چهارم — «فرمان‌های عقل» را می‌شمارد — که «توصیفِ انسان آزاد»‌اند نه «دستور»: انسان آزاد — از مرگ «کمترین» می‌اندیشد — زیرا می‌داند مرگ — که از بیرون می‌آید — را نمی‌توان با ترس برد؛ و به «زندگی» می‌اندیشد. انسان آزاد — «سخاوتمند» است — زیرا می‌داند یاریِ دیگران، یاریِ خود است. انسان آزاد — «راست» است — زیرا می‌داند دروغ — که اعتماد را می‌شکند — به ضرر خود است؛ و «نمک‌نشناس» نیست — زیرا می‌داند سپاس، پیوندِ جامعه را می‌سازد. این «انسان آزاد» — که اسپینوزا او را «الگو» می‌خواند — چون «ایده‌ای» است که می‌سنجیم نه «دستوری» که اطاعت کنیم — و این تفاوت، روح اخلاق اسپینوزایی است."]),
  ch("b-wph-9", 28, "بخش پنجم؛ قدرت فهم", ["بخش پنجم — «دربارهٔ قدرت فهم، یا آزادی انسان» — اوج اخلاق است: اسپینوزا می‌گوید راه رهایی از تأثرات منفعل — «شناخت روشن» آن‌هاست؛ زیرا تأثر — تا وقتی «مبهم» است — «منفعل» است — اما وقتی «علتش» را روشن بشناسیم — «فعال» می‌شود؛ و این «فعال‌شدن» — که با «تفکیک تأثر از ایدهٔ علت بیرونی» می‌شود — «قدرت» می‌آورد. مثلاً: غم — که از «زیان» برمی‌خیزد — وقتی بفهمیم که این زیان — «از ضرورت طبیعت» بود و نمی‌توانست جز این باشد — از «غم منفعل» به «فهم فعال» بدل می‌شود. این روش — که «بازشناخت شناختی» خوانده می‌شود — امروز، پایهٔ «درمان شناختی» است؛ و خواننده می‌بیند که اسپینوزا — چهار قرن پیش — «پزشک روح» بود."]),
  ch("b-wph-9", 29, "عشق عقلانی خدا", ["«عشق عقلانی خدا» — Amor Dei intellectualis — که اوج اخلاق است — چنین ساخته می‌شود: وقتی چیزها را — با شناخت سوم — «در خدا» می‌بینیم — یعنی می‌بینیم که از «ضرورت ذات او» برمی‌خیزند — این «فهم» — که «شادی» است — با «ایدهٔ خدا» — که علت همه‌چیز است — همراه می‌شود؛ و این «شادی همراه با ایدهٔ خدا» — «عقلانی‌ترین عشق» است. این عشق — که نه ترس از کیفر است و نه طمع پاداش — «رضایت» است؛ و اسپینوزا می‌گوید: این عشق — چون از شناخت ابدی برمی‌خیزد — «ابدی» است؛ و «نجات و سعادت و آزادی — یکی‌اند». خوانندهٔ عرفان — که «عشق» را در مثنوی خوانده — شباهت را می‌بیند؛ اما راه را نیز: عشق اسپینوزا — از «فهم» می‌آید نه از «جذبه»."]),
  ch("b-wph-9", 30, "سعادت؛ پاداش نیست", ["آخرین قضیه‌های اخلاق — که از زیباترین صفحات اسپینوزا هستند — می‌گویند: «سعادت — پاداش فضیلت نیست — خودِ فضیلت است» — یعنی رهایی — نه «بعد از» فهم — که «در» فهم است؛ و ما — چون «می‌فهمیم» — آزادیم — نه چون «آزاد شدیم» می‌فهمیم. این وارونه‌نگری — که اخلاق را از «معامله» به «بودن» می‌برد — با جملهٔ پایانی کتاب کامل می‌شود: «راهی که من نشان دادم — اگرچه دشوار می‌نماید — اما یافتنی است؛ زیرا اگر نایافتنی بود — چگونه ممکن بود که چنین کم، به آن توجه شود؟ اما همهٔ چیزهای شریف — چنان‌که نادرند — دشوارند». این جمله — که وصیت اسپینوزاست — برای هر خوانندهٔ جدی — چراغ راه است."]),
  ch("b-wph-9", 31, "رسالهٔ الهی-سیاسی؛ آزادی تفکر", ["رسالهٔ الهی-سیاسی اسپینوزا — که در ۱۶۷۰، بی‌نام منتشر شد — از شجاع‌ترین کتاب‌های تاریخ است: اسپینوزا — که می‌خواست «آزادی فلسفیدن» را دفاع کند — کتاب مقدس را — با روش «تاریخی-انتقادی» — خواند: نویسنده‌هایش را شمرد، تناقض‌هایش را نشان داد، و گفت: هدف کتاب مقدس — «اطاعت» است نه «حقیقت» — پس نباید با «فلسفه» ستیز کند. و نتیجه: «هدف دولت — نه سلطه بر انسان‌ها — که آزادی آنان است» — دولتی که بخواهد «اندیشه‌ها» را فرمان ببرد — نه تنها ظالم — که «غیرممکن» است؛ زیرا اندیشه را نمی‌توان فرمان برد. این رساله — که بر روشنگری اثر گذاشت — از بنیان‌های «آزادی بیان» است."]),
  ch("b-wph-9", 32, "رسالهٔ سیاسی؛ دموکراسی", ["رسالهٔ سیاسی اسپینوزا — که ناتمام ماند — از او «دموکرات» می‌سازد: اسپینوزا — که چون هابز، قدرت را از «طبیعت» می‌گیرد — اما نتیجهٔ دیگری می‌گیرد: چون «قدرت» — «حق» است — و قدرت «همه» — از قدرت «یکی» بیشتر است — پس «دموکراسی» — که قدرت همه را جمع می‌کند — «طبیعی‌ترین» رژیم است. و دموکراسی — برای اسپینوزا — نه فقط «کارآمدترین» — که «عقلانی‌ترین» است؛ زیرا در دموکراسی — که همه در قانون شریک‌اند — «اطاعت از قانون» — «اطاعت از خود» است — و این، «آزادی» است. این دفاع — که در قرن هفدهم بی‌سابقه بود — اسپینوزا را از «پیشگامان دموکراسی مدرن» می‌سازد."]),
  ch("b-wph-9", 33, "تکفیر؛ زندگی اسپینوزا", ["باروخ اسپینوزا — که در ۱۶۳۲، در خانواده‌ای یهودی پرتغالی در آمستردام به دنیا آمد — در بیست‌وچهارسالگی — ۱۶۵۶ — «تکفیر» شد: جامعهٔ یهودی — که از «عقاید خطرناک»‌اش ترسید — او را با حکمی که از شدیدترین اسناد تاریخی است — «از ملت اسرائیل جدا کرد» — و فرمان داد که «کسی با او سخن نگوید و نزدیکش نشود». اسپینوزا — که این حکم را «آزادکننده» خواند — از جامعهٔ دینی بیرون رفت و با «تراشیدن عدسی» — که سلامتیش را نیز گرفت — زندگی‌اش را ساخت؛ و در چهل‌وچهارسالگی — ۱۶۷۷ — درگذشت. این زندگی — که «فلسفیدن» را با «تنهایی» و «فقر» بهایی داد — خود، نمونه‌ای از «انسان آزاد» است که اخلاقش توصیف کرد."]),
  ch("b-wph-9", 34, "اسپینوزا و دکارت؛ وارث و منکر", ["اسپینوزا — که جوانی‌اش را در حلقهٔ دکارتیان گذراند و «اصول فلسفهٔ دکارت» را نوشت — از دکارت «روش» گرفت — اما نتیجه‌ای گرفت که دکارت را «وحشت» می‌داد: دکارت — که «دو جوهر» می‌گفت — را با همان تعریف دکارتی جوهر — «آنچه به غیر نیاز ندارد» — به «یک جوهر» رساند؛ و دکارت — که «ارادهٔ آزاد» را ستون اخلاق می‌دانست — را با همان «روشنی» که دکارت می‌ستود — به «جبر» رساند. این حرکت — که «وفاداری تا خیانت» خوانده شده — درس روشی بزرگی است: اصول — اگر جدی گرفته شوند — از بنیان‌گذارشان می‌گذرند؛ و خواننده می‌بیند که تاریخ فلسفه — نه سلسلهٔ نظریه‌ها — که «گفت‌وگوی اصول» است."]),
  ch("b-wph-9", 35, "اسپینوزا و موسی بن میمون؛ میراث یهودی", ["اسپینوزا — که در مدرسهٔ یهودی آمستردام، «راهنمای سرگشتگان» ابن‌میمون را خواند — از او «تنزیه» گرفت: ابن‌میمون — که صفات «مثبت» خدا را — چون «دانا» و «توانا» — به معنای «سلبی» می‌خواند تا «تشبیه» نشود — راهی گشود که اسپینوزا — با جبرگرایی‌اش — تا انتها رفت. اما اسپینوزا — از ابن‌میمون — «تفسیر عقلانی کتاب مقدس» را نیز گرفت — و آن را — چنان‌که در رسالهٔ الهی-سیاسی دیدیم — «تاریخی» کرد. این رابطه — که «یهودی‌ستیزان» از آن برای طرد اسپینوزا استفاده کردند — خود، از موضوعات جالب تاریخ اندیشه است: چگونه یک سنت — هم «مادر» است و هم «قاضی»."]),
  ch("b-wph-9", 36, "مناقشهٔ همه‌خدایی؛ یاکوبی و لسینگ", ["اسپینوزا — که در قرن هفدهم، «ملحد» خوانده می‌شد — در قرن هجدهم، ناگهان «قدیس» شد؛ و ریشهٔ این وارونگی، «مناقشهٔ همه‌خدایی» بود: یاکوبی — که فاش کرد لسینگ — شاعر بزرگ آلمان — «اسپینوزیست» بوده — هشدار داد که «فلسفهٔ سازگار — به اسپینوزیسم می‌انجامد» — یعنی جبر و همه‌خدایی؛ و این، اروپا را تکان داد. اما همین تکان — هردر و گوته و بعدها هگل را — به اسپینوزا کشاند؛ و هگل جمله‌ای معروف گفت: «یا اسپینوزیست هستی یا اصلاً فیلسوف نیستی». این مناقشه — که اسپینوزا را از «ملحد» به «خداپرست‌ترین فیلسوف» بدل کرد — از شگفت‌انگیزترین رویدادهای تاریخ پذیرش است."]),
  ch("b-wph-9", 37, "هگل؛ اسپینوزا و آرمان‌گرایی", ["هگل — که اسپینوزا را «نقطهٔ عزیمت همهٔ فلسفهٔ مدرن» می‌دانست — از او «وحدت» گرفت — اما «سکون»‌اش را نکوهید: جوهر اسپینوزایی — که همه‌چیز از آن برمی‌خیزد — «ساکن» است؛ و هگل — که «سوژه» و «تاریخ» را می‌خواست — گفت: جوهر باید «سوژه» شود — یعنی خود را در تاریخ «بشناسد». این نقد — که آرمان‌گرایی آلمانی را ساخت — درست بود؛ اما وارثان هگل — از مارکس تا دُلوز — دوباره به اسپینوزا بازگشتند؛ و خواننده می‌بیند که تاریخ فلسفه — چون رودی — گاه از اسپینوزا دور می‌شود — اما همیشه به او بازمی‌گردد؛ و این بازگشت‌ها — که در قرن بیستم شتاب گرفت — از نشانه‌های «کلاسیک بودن» اخلاق است."]),
  ch("b-wph-9", 38, "نیچه؛ پیشگام فراسوی نیک و بد", ["نیچه — که در نامه‌ای به دوستش نوشت «از اسپینوزا شگفت‌زده‌ام» — پنج نقطهٔ اشتراک با او شمرد: انکار ارادهٔ آزاد، انکار غایت‌مندی، انکار نظم اخلاقی جهان، انکار خودِ غیرخودی، و «فهمیدن» به‌جای «نفرت». نیچه — که «فراسوی نیک و بد» را می‌خواست — در اسپینوزا — که نیک و بد را «مفید و مضر» خوانده بود — «پیشگام» خود را یافت. اما تفاوتشان نیز عمیق است: نیچه — که «ارادهٔ معطوف به قدرت» را می‌خواست — جبرگرایی آرام اسپینوزا را — که به «رضایت» می‌انجامد — نیمه گذاشت؛ و خواننده می‌بیند که حتی نزدیک‌ترین وارثان — از «میراث» — آنچه می‌خواهند برمی‌دارند؛ و این، قانون تاریخ فلسفه است."]),
  ch("b-wph-9", 39, "برگسون؛ شهود در برابر هندسه", ["برگسون — که رسالهٔ دکترایش دربارهٔ اسپینوزا بود — از او «شهود» گرفت — اما «هندسه»‌اش را نکوهید: اسپینوزا — که می‌خواست همه‌چیز را «به شیوهٔ هندسی» بسازد — «زمان» را — که برگسون آن را «دوره» می‌خواند — به «فضا» فروکاهد؛ و این فروکاست — که ریشهٔ جبرگرایی اسپینوزاست — از نظر برگسون، «خطای اصلی» اوست. این نقد — که درست یا نادرست — از عمیق‌ترین نقدهای بر اخلاق است؛ زیرا نشان می‌دهد «روش» — که اسپینوزا آن را «پیام» می‌دانست — می‌تواند خود «مشکل» باشد؛ و خواننده می‌بیند که فلسفه — حتی دربارهٔ بزرگ‌ترین فیلسوفان — «گفت‌وگو» است نه «پرستش»."]),
  ch("b-wph-9", 40, "دُلوز؛ شاهزادهٔ فیلسوفان", ["ژیل دُلوز — که رساله‌اش «اسپینوزا و مسئلهٔ بیان» است و «اسپینوزا؛ عمل‌گرایی فلسفی» را نوشت — اسپینوزا را «شاهزادهٔ فیلسوفان» خواند: فیلسوفی که «بیان» — نه «تضاد» — را بنیاد می‌داند؛ «شادی» — نه «گناه» — را معیار اخلاق می‌سازد؛ و «مشترک» — نه «ملکیت» — را پایهٔ اجتماع می‌نهد. دُلوز — که اسپینوزا را «فلسفهٔ زندگی» می‌خواند — او را از «جبرگرای آرام» به «انقلابیِ تأثرات» بدل کرد؛ و خوانش او — که بر فلسفهٔ معاصر — از نگری تا برایدوتی — اثر گذاشت — از زنده‌ترین خوانش‌های اسپینوزاست؛ و خواننده می‌بیند که هر نسل — اسپینوزای «خود» را می‌سازد — و این، نشانهٔ زنده‌بودن اخلاق است."]),
  ch("b-wph-9", 41, "دامازیو؛ مغز و اسپینوزا", ["آنتونیو دامازیو — عصب‌شناس معاصر — در «جست‌وجوی اسپینوزا» — که از پرفروش‌ترین کتاب‌های علوم اعصاب است — نشان می‌دهد که اسپینوزا — چهار قرن پیش — بسیاری از یافته‌های امروز را «پیش‌بینی» کرد: تأثرات — که از «بدن» برمی‌خیزند و بر «تصمیم‌ها» اثر می‌گذارند — نه «دشمن عقل» — که «شریک» آن‌اند؛ و «ذهن» — که «ایدهٔ بدن» است — با بدن «یکی» است — چنان‌که علوم اعصاب امروز می‌گوید. دامازیو — که اسپینوزا را «فیلسوفِ احساس» می‌خواند — می‌گوید: اگر فلسفه، «علمی» می‌شد — اسپینوزا — نه دکارت — الگویش بود. این بازکشف — که فلسفه و علوم اعصاب را به هم می‌رساند — از شگفت‌انگیزترین رویدادهای فلسفهٔ معاصر است."]),
  ch("b-wph-9", 42, "اسپینوزا و محیط‌زیست؛ بوم‌شناسی عمیق", ["اسپینوزا — که انسان را «حالتی از طبیعت» می‌داند نه «فرمانروای» آن — برای «بوم‌شناسی عمیق» — که آر نِس آن را ساخت — از مهم‌ترین منابع است: اگر انسان — چون همه‌چیز — «حالتی از خدا-طبیعت» است — پس «سلطه بر طبیعت» — که دکارت می‌خواست — «خودزنی» است؛ و «حفظ طبیعت» — «حفظ خود» است. این نگاه — که امروز، در بحران اقلیمی، از نو خوانده می‌شود — نشان می‌دهد اسپینوزا — با همهٔ عقل‌گرایی‌اش — «اخلاق محیط‌زیستی» را نیز می‌سازد؛ و خواننده می‌بیند که متون کلاسیک — اگر جدی خوانده شوند — برای «مسائل نوظهور» نیز راه‌گشایند."]),
  ch("b-wph-9", 43, "اخلاق در برابر شر؛ مسئلهٔ عدالت", ["اخلاق اسپینوزا — که «خدا» را از «اراده و هدف» می‌رهاند — با «مسئلهٔ شر» نیز روبه‌روست: اگر همه‌چیز — از ضرورت ذات خدا برمی‌خیزد — پس «شر» — که ما می‌بینیم — از کجاست؟ پاسخ اسپینوزا — که در نامه‌هایش مفصل شده — این است: «شر» — چون «خوب» — «نسبی» است: آنچه «برای ما» شر است — در «کل طبیعت» — شر نیست؛ چنان‌که طوفان — که برای کشتی شر است — برای اقیانوس، «طبیعی» است. این پاسخ — که برای قربانیان، «سرد» می‌نماید — برای فیلسوف، «آزادکننده» است؛ و خواننده می‌بیند که هر پاسخی به مسئلهٔ شر — از این پاسخ اسپینوزایی تا پاسخ‌های کلامی — «هزینه‌ای» دارد؛ و هنر فلسفه، در «دیدن هزینه‌ها» است."]),
  ch("b-wph-9", 44, "اسپینوزا و سیاست امروز؛ دموکراسی رادیکال", ["اسپینوزا — که «قدرت همه» را بنیاد دموکراسی می‌دانست — برای «دموکراسی رادیکال» معاصر — که نگری و هارت آن را ساختند — از مهم‌ترین منابع است: «توده» — که اسپینوزا آن را «مولتیتودو» می‌خواند — نه «تودهٔ بی‌شکل» است و نه «ملت یکپارچه» — «کثرتی» است که می‌تواند — بی‌آنکه «یکی» شود — «مشترک» بسازد. این مفهوم — که دموکراسی را نه «نمایندگی» — که «حضور» می‌داند — از زنده‌ترین مفاهیم فلسفهٔ سیاسی امروز است؛ و خواننده می‌بیند که اسپینوزا — که چهار قرن پیش — برای «آزادی فلسفیدن» تکفیر شد — امروز، برای «دموکراسیِ فردا» خوانده می‌شود."]),
  ch("b-wph-9", 45, "اسپینوزا و دین؛ خدای اینشتین", ["اسپینوزا — که «ملحد» خوانده می‌شد — اما «خدای» او — که اینشتین آن را می‌پرستید — از زنده‌ترین مفاهیم الهیاتی معاصر است: وقتی از اینشتین پرسیدند «به خدا باور داری؟» — پاسخ داد: «به خدای اسپینوزا — که در هماهنگیِ قانونمندِ همهٔ آنچه هست آشکار می‌شود — باور دارم؛ نه به خدایی که در سرنوشت و کردار انسان‌ها دخالت می‌کند». این «خدای اینشتین» — که نه شخص است و نه ناظر — «شگفتیِ عقلانی» است؛ و خواننده می‌بیند که اسپینوزا — با همهٔ جبرگرایی‌اش — راهی برای «معنویت بی‌خرافه» گشود که برای انسانِ علمیِ امروز، از جذاب‌ترین راه‌هاست."]),
  ch("b-wph-9", 46, "اخلاق در ایران؛ ترجمه و reception", ["اخلاق اسپینوزا — که محسن جهانگیری آن را — با مقدمه‌ای مفصل — به فارسی برگرداند — برای خوانندهٔ ایرانی، دو گفت‌وگوی ویژه می‌سازد: نخست، با «وحدت وجود» — که در عرفان اسلامی خواندیم — و خواننده می‌بیند که اسپینوزا — با برهان — به جایی نزدیک می‌شود که ابن‌عربی — با شهود — رسید؛ اما راه‌ها و نتیجه‌ها — یکی نیستند. و دوم، با «جبر و اختیار» — که در کلام خواندیم — و خواننده می‌بیند که پاسخ اسپینوزا — «آزادی به‌مثابه شناخت ضرورت» — یکی از راه‌حل‌های این مناقشهٔ هزارساله است؛ و این گفت‌وگوها — که نباید به پذیرش یا ردّ بینجامند — از آموزنده‌ترین تمرین‌های فلسفهٔ تطبیقی‌اند."]),
  ch("b-wph-9", 47, "چگونه اخلاق را بخوانیم", ["برای خواندن اخلاق — که با فرم هندسی‌اش می‌ترساند — این روش پیشنهاد می‌شود: نخست، «تعریف‌ها» و «اصول موضوعهٔ» هر بخش را — که کلیدهای آن‌اند — با دقت بخوانید و «دفترچهٔ واژه‌ها» بسازید — جوهر، صفت، حالت، کوناتوس. دوم، قضیه‌ها را — نه یکی‌یکی — که «خوشه‌ای» بخوانید — زیرا هر قضیه، به قضیه‌های پیشین تکیه دارد؛ و نقشهٔ این تکیه‌ها را بکشید. سوم، بخش‌های سوم و چهارم — که «تأثرات»‌اند — را با «زندگی خود» بخوانید — و ببینید کدام تأثرات‌تان «فعال»‌اند و کدام «منفعل». و چهارم — «ضمیمه‌ها» و «نامه‌ها» را بخوانید — که اسپینوزا، در آن‌ها — ساده‌تر سخن می‌گوید. با این روش، اخلاق — از «هندسه‌ای خشک» — به «نقشهٔ روح» بدل می‌شود."]),
  ch("b-wph-9", 48, "نامه‌های اسپینوزا؛ فیلسوف در گفت‌وگو", ["نامه‌های اسپینوزا — که بیش از هشتاد تای آن به جا مانده — چهرهٔ دیگری از او می‌نمایاند: فیلسوفی که با «پرسش‌های واقعی» — از مسئلهٔ بی‌نهایت تا سیاست هلند — روبه‌روست و با «صبر» پاسخ می‌دهد. نامه‌های او به «دو بلیس» — که از منتقدانش بود — از زیباترین اسناد «گفت‌وگوی فلسفی»‌اند: اسپینوزا — که می‌توانست تندی کند — با «احترام» و «دقت» پاسخ می‌دهد؛ و می‌گوید: «من — نه می‌خندم و نه می‌گریم — می‌فهمم». این جمله — که خلاصهٔ روش اوست — برای خوانندهٔ مکتب‌خانه — که می‌خواهد «گفت‌وگوکننده» شود — درس است؛ و نامه‌ها — که باید در کنار اخلاق خوانده شوند — نشان می‌دهند فلسفه — نه در انزوا — که در «گفت‌وگو» پخته می‌شود."]),
  ch("b-wph-9", 49, "جمع‌بندی؛ اسپینوزا و رهایی", ["پنجاه فصل این سیر — از جوهر تا عشق عقلانی خدا — اخلاق را پیمود؛ و اکنون خواننده می‌داند که این کتاب — با همهٔ فرم هندسی‌اش — «کتاب رهایی» است: رهایی از «ترس» — که از جهل به علل می‌آید؛ رهایی از «نفرت» — که از غمِ بی‌فهم می‌آید؛ و رهایی از «توهم آزادی» — که به «بردگیِ تأثرات» می‌انجامد. راه اسپینوزا — که فهم است — برای خوانندهٔ امروز — که با اضطراب‌ها و اعتیادها و نفرت‌ها می‌جنگد — «راه» است؛ و جملهٔ پایانی اخلاق — «همهٔ چیزهای شریف — چنان‌که نادرند — دشوارند» — برای هر خوانندهٔ جدی — «وصیت» است؛ و خواننده‌ای که اخلاق را خوانده، دیگر نمی‌تواند «بردهٔ تأثرات» باشد — بی‌آنکه بداند؛ و این، آغاز رهایی است.", ["پروژه‌های پیشنهادی", "برای مقطع پژوهشی، چند پروژه پیشنهاد می‌شود: «وحدت وجود اسپینوزایی و صدرایی؛ دو تقریر از یکی»؛ «کوناتوس و ارادهٔ معطوف به قدرت؛ اسپینوزا و نیچه»؛ «تقلید تأثرات و شبکه‌های اجتماعی»؛ و «جبر اسپینوزا و جبر اشعری؛ دو راه‌حل برای یک مسئله». هر یک از این پروژه‌ها — اگر با خوانش مستقیم اخلاق و روش تطبیقی انجام شود — می‌تواند خواننده را از خوانندهٔ اسپینوزا، به گفت‌وگوکننده با اسپینوزا برساند."]]),
];

